import { z } from "zod";

const clientEnvSchema = z.object({
    NEXT_PUBLIC_APP_URL: z.url(),
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: z.string(),
    NEXT_PUBLIC_SUPABASE_STORAGE_BUCKET_NAME: z.string(),
    NEXT_PUBLIC_SUPABASE_TUS_ENDPOINT: z.string()
});

export const env = clientEnvSchema.parse({
    NEXT_PUBLIC_APP_URL: process.env.NEXT_PUBLIC_APP_URL,
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY:
        process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
    NEXT_PUBLIC_SUPABASE_STORAGE_BUCKET_NAME:
        process.env.NEXT_PUBLIC_SUPABASE_STORAGE_BUCKET_NAME,
    NEXT_PUBLIC_SUPABASE_TUS_ENDPOINT:
        process.env.NEXT_PUBLIC_SUPABASE_TUS_ENDPOINT,
});
